def once(text, old, new):
    if text.count(old)!=1: raise ValueError('GSPlugin anchor drift: '+repr(old[:80]))
    return text.replace(old,new,1)

def transform(text,restore=False):
    if '#include "htcleogsplugintrace.inl"' in text:
        for old,new in reversed(EDITS): text=once(text,new,old)
    elif 'HtcleoGsPlugin' in text: raise ValueError('Partial plugin observation')
    if hashlib.sha256(text.encode('latin-1')).hexdigest()!=BASE_SOURCE:
        raise ValueError('GSPluginLoader differs from exact820 source')
    if not restore:
        for old,new in EDITS: text=once(text,old,new)
    return text

def code_mmp(text,baseline=False):
    if hashlib.sha256(text.encode('latin-1')).hexdigest()!=BASE_MMP:
        raise ValueError('GSFramework MMP drift')
    text,n=re.subn(r'^START RESOURCE[^\n]*\n.*?^END[^\n]*\n','',text,flags=re.M|re.S)
    if n!=2: raise ValueError('Expected two frozen-resource sections')
    text=re.sub(r'^DOCUMENT[^\n]*\n','',text,flags=re.M)
    # SBS appends version/UID itself. Including a version here doubles it in
    # consumer import names; the DLL executable/exports are unchanged.
    text += '\nDEFFILE ../EABI/GSFramework.DEF\nLINKAS gsframework.dll\n'
    if baseline: text=once(text,'TARGET      gsframework.dll','TARGET      gsframework_baseline.dll')
    return text

def main():
    p=argparse.ArgumentParser();p.add_argument('root',type=Path)
    mode=p.add_mutually_exclusive_group();mode.add_argument('--restore',action='store_true');mode.add_argument('--baseline',action='store_true');a=p.parse_args()
    root=a.root/REL;path=root/'src/GSPluginLoader.cpp'
    old=path.read_text(encoding='latin-1');new=transform(old,a.restore or a.baseline)
    if transform(new,True)!=transform(old,True): raise ValueError('Plugin inverse failed')
    if not (a.restore or a.baseline) and transform(new)!=new: raise ValueError('Plugin idempotence failed')
    if old!=new: path.write_text(new,encoding='latin-1')
    deffile=root.parent/'EABI/GSFrameworkU.DEF'
    if hashlib.sha256(deffile.read_bytes()).hexdigest()!=BASE_DEF: raise ValueError('Frozen export DEF drift')
    alias=deffile.with_name('GSFrameworku.DEF')
    if not alias.exists(): alias.symlink_to(deffile.name)
    if alias.read_bytes()!=deffile.read_bytes(): raise ValueError('DEF case alias drift')
    if not a.restore:
        suffix='baseline' if a.baseline else 'htcleo'
        (root/('GSFramework_'+suffix+'.mmp')).write_text(code_mmp((root/'GSFramework.mmp').read_text(encoding='latin-1'),a.baseline),encoding='latin-1')
        helper=HERE.parent/'hd2/qsd8250-native-bsp/diagnostics/htcleogsplugintrace.inl'
        (root/'src/htcleogsplugintrace.inl').write_bytes(helper.read_bytes())
    print('HTCLEO_GSAPP_PLUGIN='+('restored' if a.restore else 'host-baseline' if a.baseline else 'GS-root-first2-native-RunL-LoadNext-RunError-bounded-no-policy-change'))

if __name__=='__main__': main()
